#include <list>
#include <algorithm>

int main() {
    std::list<int> L1 = {0, 2, 4};
    std::list<int> L2 = {1, 3, 5};

    // L1 and L2 must be sorted (they are)
    L1.merge(L2);

    // L1 is now {0, 1, 2, 3, 4, 5}
    // L2 is empty

    if (L2.empty()) {
        // Success: L2 is empty after merge
    }
    // Note: L1.sort() and L2.sort() must precede merge if not guaranteed sorted.
}
